  });

  it('returns label unchanged if length equals width', () => {
    expect(formatFixedWidthLabel('hello', 5)).toBe('hello');
  });

  it('truncates and adds ellipsis if label is longer', () => {
    expect(formatFixedWidthLabel('longlabel', 5)).toBe('long…');
