describe('setRandomBackground', () => {
  let originalGetElementById;
  let bgDiv;
  let imageMock;
  let originalImage;

  beforeEach(() => {
    // Mock document.getElementById
    bgDiv = { style: { backgroundImage: '' } };
    originalGetElementById = global.document.getElementById;
    global.document.getElementById = jest.fn((id) => (id === 'bg' ? bgDiv : null));

    // Mock Image
    imageMock = {
      set src(val) {
        // Simulate successful load for the first image
        setTimeout(() => {
          if (this.onload) this.onload();
        }, 0);
      },
      set onload(fn) {
        this._onload = fn;
      },
      get onload() {
        return this._onload;
      },
      set onerror(fn) {
        this._onerror = fn;
      },
      get onerror() {
        return this._onerror;
      },
    };
    originalImage = global.Image;
    global.Image = jest.fn(() => imageMock);
  });

  afterEach(() => {
    global.document.getElementById = originalGetElementById;
    global.Image = originalImage;
    jest.clearAllMocks();
  });

  it('sets a random background image when bg element exists', (done) => {
    setRandomBackground();
    setTimeout(() => {
      expect(bgDiv.style.backgroundImage).toMatch(/^url\("images\//);
      done();
    }, 10);
  });

  it('does nothing if bg element does not exist', () => {
    global.document.getElementById = jest.fn(() => null);
    expect(() => setRandomBackground()).not.toThrow();
  });

  it('tries next image on error until one loads', (done) => {
    let callCount = 0;
    global.Image = jest.fn(() => {
      callCount++;
      return {
        set src(val) {
          if (callCount < 2) {
            setTimeout(() => {
              if (this.onerror) this.onerror();
            }, 0);
          } else {
            setTimeout(() => {
              if (this.onload) this.onload();
            }, 0);
          }
        },
        set onload(fn) {
          this._onload = fn;
        },
        get onload() {
          return this._onload;
        },
        set onerror(fn) {
          this._onerror = fn;
        },
        get onerror() {
          return this._onerror;
        },
      };
    });
    setRandomBackground();
    setTimeout(() => {
      expect(bgDiv.style.backgroundImage).toMatch(/^url\("images\//);
      expect(callCount).toBeGreaterThan(1);
      done();
    }, 20);
  });
});

