import { describe, it, expect, vi, beforeEach } from 'vitest';
import React from 'react';
import { runPhase4Confirm } from '../../src/phases/phase4_confirm';
import * as ink from 'ink';

describe('runPhase4Confirm', () => {
	const baseDetails = {
		model: 'gpt-4.1',
		workingDirectory: '/home/user/project',
		enhancedTokens: 1234,
		timeoutMs: 60000,
	};

	let origRender: typeof ink.render;
	let origUseApp: typeof ink.useApp;
	let origUseInput: typeof ink.useInput;
	let exitMock: ReturnType<typeof vi.fn>;
	let inputHandler: ((input: string, key: any) => void) | undefined;

	beforeEach(() => {
		origRender = ink.render;
		origUseApp = ink.useApp;
		origUseInput = ink.useInput;

		exitMock = vi.fn();
		vi.spyOn(ink, 'useApp').mockReturnValue({ exit: exitMock });
		vi.spyOn(ink, 'useInput').mockImplementation((handler) => {
			inputHandler = handler;
		});
	});

	afterEach(() => {
		vi.restoreAllMocks();
		inputHandler = undefined;
	});

	it('resolves with ok result when Enter is pressed (happy path)', async () => {
		const unmount = vi.fn();
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			// Simulate input after render
			setTimeout(() => {
				inputHandler && inputHandler('', { return: true });
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(baseDetails);
		expect(result.ok).toBe(true);
		expect(result.value).toBeUndefined();
		expect(exitMock).toHaveBeenCalled();
		expect(unmount).toHaveBeenCalled();
	});

	it('resolves with cancelled result when Esc is pressed', async () => {
		const unmount = vi.fn();
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			setTimeout(() => {
				inputHandler && inputHandler('', { escape: true });
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(baseDetails);
		expect(result.ok).toBe(false);
		expect(result.reason).toBe('cancelled');
		expect(result.message).toBe('Phase 4 skipped by user.');
		expect(exitMock).toHaveBeenCalled();
		expect(unmount).toHaveBeenCalled();
	});

	it('resolves with cancelled result when "q" is pressed', async () => {
		const unmount = vi.fn();
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			setTimeout(() => {
				inputHandler && inputHandler('q', {});
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(baseDetails);
		expect(result.ok).toBe(false);
		expect(result.reason).toBe('cancelled');
		expect(result.message).toBe('Phase 4 skipped by user.');
		expect(exitMock).toHaveBeenCalled();
		expect(unmount).toHaveBeenCalled();
	});

	it('ignores input after already done', async () => {
		const unmount = vi.fn();
		let callCount = 0;
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			setTimeout(() => {
				// First input triggers done
				inputHandler && inputHandler('', { return: true });
				// Second input should be ignored
				inputHandler && inputHandler('', { escape: true });
				callCount++;
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(baseDetails);
		expect(result.ok).toBe(true);
		expect(exitMock).toHaveBeenCalledTimes(1);
		expect(unmount).toHaveBeenCalled();
		expect(callCount).toBe(1);
	});

	it('renders with edge-case values (zero tokens, long dir, large timeout)', async () => {
		const details = {
			model: 'edge-model',
			workingDirectory: '/a/very/long/path/that/should/be/handled/correctly/by/the/panel',
			enhancedTokens: 0,
			timeoutMs: 9999999,
		};
		const unmount = vi.fn();
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			setTimeout(() => {
				inputHandler && inputHandler('', { return: true });
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(details);
		expect(result.ok).toBe(true);
		expect(exitMock).toHaveBeenCalled();
		expect(unmount).toHaveBeenCalled();
	});

	it('handles negative and non-integer token/timeout values gracefully', async () => {
		const details = {
			model: 'test-model',
			workingDirectory: '/tmp',
			enhancedTokens: -42,
			timeoutMs: 12345.67,
		};
		const unmount = vi.fn();
		vi.spyOn(ink, 'render').mockImplementation((el) => {
			setTimeout(() => {
				inputHandler && inputHandler('', { return: true });
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(details);
		expect(result.ok).toBe(true);
		expect(exitMock).toHaveBeenCalled();
		expect(unmount).toHaveBeenCalled();
	});

	it('calls unmount and resolves even if onDone is called multiple times', async () => {
		const unmount = vi.fn();
		let onDoneRef: ((result: any) => void) | undefined;
		vi.spyOn(ink, 'render').mockImplementation((el: any) => {
			// Find the onDone prop
			const props = el.props;
			onDoneRef = props.onDone;
			setTimeout(() => {
				onDoneRef && onDoneRef({ ok: true, value: undefined });
				onDoneRef && onDoneRef({ ok: false, reason: 'cancelled', message: 'Phase 4 skipped by user.' });
			}, 0);
			return { unmount };
		});

		const result = await runPhase4Confirm(baseDetails);
		expect(result.ok).toBe(true);
		expect(unmount).toHaveBeenCalled();
	});
});
