import type { ReverseGeocoder, GeoAddress } from '../../../src/domain/ports/ReverseGeocoder';

describe('ReverseGeocoder interface', () => {
  class MockReverseGeocoder implements ReverseGeocoder {
    async reverseGeocode(latitude: number, longitude: number): Promise<GeoAddress> {
      if (typeof latitude !== 'number' || typeof longitude !== 'number') {
        throw new Error('Invalid coordinates');
      }
      if (latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
        throw new Error('Coordinates out of bounds');
      }
      if (latitude === 0 && longitude === 0) {
        // Simulate not found
        return {
          street: null,
          streetNumber: null,
          complement: null,
          neighborhood: null,
          city: null,
          metropolitanRegion: null,
          state: null,
          stateCode: null,
          postalCode: null,
          country: 'Nowhere',
        };
      }
      // Simulate happy path
      return {
        street: 'Main St',
        streetNumber: '1',
        complement: null,
        neighborhood: 'Downtown',
        city: 'Metropolis',
        metropolitanRegion: 'Metro Area',
        state: 'StateName',
        stateCode: 'ST',
        postalCode: '12345',
        country: 'Countryland',
      };
    }
  }

  let geocoder: ReverseGeocoder;

  beforeEach(() => {
    geocoder = new MockReverseGeocoder();
  });

  it('should resolve valid coordinates to a GeoAddress (happy path)', async () => {
    const result = await geocoder.reverseGeocode(40.7128, -74.0060);
    expect(result).toEqual({
      street: 'Main St',
      streetNumber: '1',
      complement: null,
      neighborhood: 'Downtown',
      city: 'Metropolis',
      metropolitanRegion: 'Metro Area',
      state: 'StateName',
      stateCode: 'ST',
      postalCode: '12345',
      country: 'Countryland',
    });
  });

  it('should return a GeoAddress with mostly nulls for (0,0) coordinates (edge case)', async () => {
    const result = await geocoder.reverseGeocode(0, 0);
    expect(result).toEqual({
      street: null,
      streetNumber: null,
      complement: null,
      neighborhood: null,
      city: null,
      metropolitanRegion: null,
      state: null,
      stateCode: null,
      postalCode: null,
      country: 'Nowhere',
    });
  });

  it('should throw an error for latitude out of bounds', async () => {
    await expect(geocoder.reverseGeocode(100, 0)).rejects.toThrow('Coordinates out of bounds');
    await expect(geocoder.reverseGeocode(-100, 0)).rejects.toThrow('Coordinates out of bounds');
  });

  it('should throw an error for longitude out of bounds', async () => {
    await expect(geocoder.reverseGeocode(0, 200)).rejects.toThrow('Coordinates out of bounds');
    await expect(geocoder.reverseGeocode(0, -200)).rejects.toThrow('Coordinates out of bounds');
  });

  it('should throw an error for non-numeric latitude or longitude', async () => {
    // @ts-expect-error
    await expect(geocoder.reverseGeocode('not-a-number', 0)).rejects.toThrow('Invalid coordinates');
    // @ts-expect-error
    await expect(geocoder.reverseGeocode(0, 'not-a-number')).rejects.toThrow('Invalid coordinates');
    // @ts-expect-error
    await expect(geocoder.reverseGeocode(null, null)).rejects.toThrow('Invalid coordinates');
    // @ts-expect-error
    await expect(geocoder.reverseGeocode(undefined, undefined)).rejects.toThrow('Invalid coordinates');
  });

  it('should satisfy the ReverseGeocoder interface contract', () => {
    expect(typeof geocoder.reverseGeocode).toBe('function');
  });
});
